/// <summary>
/// 单次批量重算允许扫描的最大 BOM 行数
/// </summary>
private const int MaxRecalculateScanRows = 5000;

/// <summary>
/// 单次批量重算允许刷新的工厂+机种+月份组数上限
/// </summary>
private const int MaxRecalculateRefreshGroups = 500;

/// <summary>
/// 按查询条件批量重算并回填机种月平均材料成本（同工厂+机种+处理月份算术平均）
/// </summary>
/// <param name="queryDto">与列表相同的筛选条件（忽略分页）</param>
/// <returns>重算统计</returns>
public async Task<TaktBomMaterialCostRecalculateModelAverageResultDto> RecalculateBomMaterialCostModelMonthlyAverageAsync(TaktBomMaterialCostQueryDto queryDto)
{
    queryDto ??= new TaktBomMaterialCostQueryDto();
    EnsureThreeLayerContext();
    if (!queryDto.BomMaterialCostStatus.HasValue)
    {
        queryDto.BomMaterialCostStatus = 1;
    }
    var predicate = QueryExpression(queryDto);
    var totalMatched = await _bomMaterialCostRepository.CountAsync(predicate);
    if (totalMatched == 0)
    {
        return new TaktBomMaterialCostRecalculateModelAverageResultDto();
    }
    if (totalMatched > MaxRecalculateScanRows)
    {
        throw new TaktBusinessException(
            $"符合条件的记录数为 {totalMatched}，超过单次重算上限 {MaxRecalculateScanRows}，请缩小查询范围。");
    }
    var rows = await _bomMaterialCostRepository.GetListForExportAsync(predicate, MaxRecalculateScanRows);
    var productModelLookup = await BuildProductModelLookupAsync();
    var patchedModelCodeRowCount = 0;
    foreach (var row in rows.Where(r => string.IsNullOrWhiteSpace(r.ModelCode)))
    {
        ApplyModelMetadata(row, productModelLookup);
        if (string.IsNullOrWhiteSpace(row.ModelCode))
        {
            continue;
        }
        await _bomMaterialCostRepository.UpdateAsync(row);
        patchedModelCodeRowCount += 1;
    }
    var refreshGroups = new HashSet<(string PlantCode, string ModelCode, int Year, int Month)>();
    foreach (var row in rows)
    {
        var plantCode = row.PlantCode?.Trim() ?? string.Empty;
        var modelCode = row.ModelCode?.Trim() ?? string.Empty;
        if (string.IsNullOrWhiteSpace(plantCode) || string.IsNullOrWhiteSpace(modelCode))
        {
            continue;
        }
        refreshGroups.Add((plantCode, modelCode, row.ProcessedDate.Year, row.ProcessedDate.Month));
    }
    if (refreshGroups.Count > MaxRecalculateRefreshGroups)
    {
        throw new TaktBusinessException(
            $"重算维度组数为 {refreshGroups.Count}，超过单次上限 {MaxRecalculateRefreshGroups}，请缩小查询范围。");
    }
    foreach (var (plantCode, modelCode, year, month) in refreshGroups)
    {
        await RefreshModelMonthlyAverageCostAsync(plantCode, modelCode, new DateTime(year, month, 1));
    }
    return new TaktBomMaterialCostRecalculateModelAverageResultDto
    {
        ScannedRowCount = rows.Count,
        PatchedModelCodeRowCount = patchedModelCodeRowCount,
        RefreshedGroupCount = refreshGroups.Count,
    };
}

