        .GroupBy(e => e.MaterialCode!, StringComparer.OrdinalIgnoreCase)
        .OrderBy(g => g.Min(x => x.SortOrder))
        .ThenBy(g => g.Key, StringComparer.Ordinal)
        .Select(g =>
