/// <summary>
/// 计算机种各月平均材料成本（仅含该月有成本的成品）
/// </summary>
/// <param name="allRows">全量转置行</param>
/// <param name="periodOrder">期间列</param>
/// <returns>各月平均成本</returns>
private static Dictionary<string, decimal> BuildModelAveragePeriodCosts(
    IReadOnlyList<TaktBomMaterialCostTransposedDto> allRows,
    IReadOnlyList<string> periodOrder)
{
    var result = new Dictionary<string, decimal>(StringComparer.Ordinal);
    foreach (var period in periodOrder)
    {
        var costs = allRows
            .Select(row => row.PeriodCosts.TryGetValue(period, out var cost) ? (decimal?)cost : null)
            .Where(c => c.HasValue)
            .Select(c => c!.Value)
            .ToList();
        if (costs.Count == 0)
        {
            continue;
        }
        result[period] = Math.Round(costs.Sum() / costs.Count, 2, MidpointRounding.AwayFromZero);
    }
    return result;
}

