private static (DateTime? Start, DateTime? End) ResolvePeriodRangeBounds(string? periodStart, string? periodEnd)
{
    DateTime? start = null;
    DateTime? end = null;
    if (!string.IsNullOrWhiteSpace(periodStart))
    {
        var (monthStart, _) = ResolvePeriodDateRange(periodStart);
        start = monthStart;
    }
    if (!string.IsNullOrWhiteSpace(periodEnd))
    {
        var (_, monthEnd) = ResolvePeriodDateRange(periodEnd);
        end = monthEnd;
    }
    if (start.HasValue && end.HasValue && start.Value > end.Value)
    {
        throw new TaktBusinessException("起始年月不能晚于结束年月");
    }
    return (start, end);
}

